script:
(function () {
  'use strict';
  // Auto loan payment with sales tax, fees, trade-in, rebate and optional extra monthly payment.
  //   Taxable amount = price - trade-in value (when the trade-in credit box is ticked), never below 0.
  //   Loan = price - rebate - down payment - trade-in value + amount owed on trade-in
  //          (+ sales tax and fees when they are financed).
  //   Payment: M = L * i / (1 - (1 + i)^-n), i = annual rate / 12, n = months (M = L / n at 0%).
  //   Total cost = price - rebate + sales tax + fees + total interest.
  // Verified in Node (scratchpad tests): $40,000 at 5% for 60 months = $754.85/mo, total interest
  //   $5,290.96 (cross-checked with a published calculator's default); $25,000 at 0% for 50 months
  //   = $500.00/mo; final balance is exactly 0; extra payments shorten the loan; no NaN on bad input.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var last = null;

  function el(id) { return document.getElementById(id); }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function monthlyPayment(principal, annualRate, months) {
    if (months <= 0 || principal <= 0) return 0;
    var i = annualRate / 12;
    if (i === 0) return principal / months;
    return principal * i / (1 - Math.pow(1 + i, -months));
  }

  function amortize(loan, annualRate, months, extra) {
    var pay = monthlyPayment(loan, annualRate, months);
    var i = annualRate / 12, bal = loan, rows = [], totalInterest = 0;
    for (var m = 1; m <= months && bal > 0.005; m++) {
      var interest = bal * i;
      var principal = Math.min(pay - interest, bal);
      var x = Math.max(0, Math.min(extra, bal - principal));
      bal -= principal + x;
      if (bal < 0.005) bal = 0;
      totalInterest += interest;
      rows.push({ n: m, interest: interest, principal: principal + x, balance: bal });
    }
    return { payment: pay, rows: rows, totalInterest: totalInterest };
  }

  function duration(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  function setText(id, text) { el(id).textContent = text; }

  function clearResults() {
    ['alPayment', 'alLoanAmount', 'alTotalInterest', 'alTotalCost', 'alSalesTax', 'alUpfront',
     'alTotalPayments', 'alPayoff'].forEach(function (id) { setText(id, '–'); });
    el('alSavings').hidden = true;
    el('alNegativeEquity').hidden = true;
    el('alSchedule').innerHTML = '';
    last = null;
  }

  function renderSchedule() {
    var head = el('alScheduleHead'), body = el('alSchedule');
    if (!last) { body.innerHTML = ''; return; }
    var html = [];
    if (el('alView').value === 'month') {
      head.innerHTML = '<tr><th scope="col">Month</th><th scope="col">Payment</th><th scope="col">Principal</th><th scope="col">Interest</th><th scope="col">Balance</th></tr>';
      last.rows.forEach(function (row) {
        html.push('<tr><td>' + row.n + '</td><td>' + money.format(row.principal + row.interest) + '</td><td>' +
          money.format(row.principal) + '</td><td>' + money.format(row.interest) + '</td><td>' + money.format(row.balance) + '</td></tr>');
      });
    } else {
      head.innerHTML = '<tr><th scope="col">Year</th><th scope="col">Principal</th><th scope="col">Interest</th><th scope="col">Ending balance</th></tr>';
      var p = 0, intr = 0;
      last.rows.forEach(function (row, idx) {
        p += row.principal; intr += row.interest;
        if (row.n % 12 === 0 || idx === last.rows.length - 1) {
          html.push('<tr><td>' + Math.ceil(row.n / 12) + '</td><td>' + money.format(p) + '</td><td>' +
            money.format(intr) + '</td><td>' + money.format(row.balance) + '</td></tr>');
          p = 0; intr = 0;
        }
      });
    }
    body.innerHTML = html.join('');
  }

  function update() {
    var price = read('alPrice'), months = read('alTerm'), rate = read('alRate'),
        down = read('alDown', true), rebate = read('alRebate', true), trade = read('alTrade', true),
        owed = read('alOwed', true), taxRate = read('alTaxRate', true), fees = read('alFees', true),
        extra = read('alExtra', true), financeCosts = el('alFinanceCosts').checked,
        tradeCredit = el('alTradeCredit').checked;
    var error = el('alError'), msg = '';
    if (isNaN(price) || price <= 0) msg = 'Enter a vehicle price greater than $0.';
    else if (isNaN(months) || months < 1 || months > 120 || months % 1 !== 0) msg = 'Enter a loan term of 1 to 120 whole months.';
    else if (isNaN(rate) || rate < 0 || rate > 40) msg = 'Enter an interest rate from 0% to 40%.';
    else if ([down, rebate, trade, owed, taxRate, fees, extra].some(function (v) { return isNaN(v) || v < 0; })) msg = 'Amounts and rates cannot be negative.';
    else if (taxRate > 20) msg = 'Enter a sales tax rate of 20% or less.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var taxable = Math.max(0, price - (tradeCredit ? trade : 0));
    var salesTax = taxable * taxRate / 100;
    var loan = price - rebate - down - trade + owed + (financeCosts ? salesTax + fees : 0);
    if (loan <= 0.005) {
      error.hidden = false;
      error.textContent = 'Your down payment, rebate and trade-in cover the full cost, so there is nothing to finance.';
      clearResults();
      return;
    }
    var base = amortize(loan, rate / 100, months, 0);
    var r = amortize(loan, rate / 100, months, extra);
    var upfront = down + (financeCosts ? 0 : salesTax + fees);

    setText('alPayment', money.format(r.payment));
    setText('alLoanAmount', money.format(loan));
    setText('alTotalInterest', money.format(r.totalInterest));
    setText('alTotalCost', money.format(price - rebate + salesTax + fees + r.totalInterest));
    setText('alSalesTax', money.format(salesTax));
    setText('alUpfront', money.format(upfront));
    setText('alTotalPayments', money.format(loan + r.totalInterest));
    setText('alPayoff', duration(r.rows.length));
    el('alNegativeEquity').hidden = !(owed > trade);
    setText('alNegativeAmount', money.format(Math.max(0, owed - trade)));
    el('alSavings').hidden = !(extra > 0);
    setText('alInterestSaved', money.format(Math.max(0, base.totalInterest - r.totalInterest)));
    setText('alTimeSaved', duration(Math.max(0, base.rows.length - r.rows.length)));

    last = { rows: r.rows };
    renderSchedule();
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('alForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    el('alView').addEventListener('change', renderSchedule);
    update();
  });
})();
